'use client'
import { useEffect, useState } from 'react'
import { usePathname, useRouter } from 'next/navigation'

export default function ProtectedWrapper({ children }: { children: React.ReactNode }) {
  const router = useRouter()
  const pathname = usePathname()
  const [checked, setChecked] = useState(false)

  useEffect(() => {
    if (!pathname) return

    // List of public routes
    const publicRoutes = ['/', '/auth', '/manga', '/premium', '/novels', '/originals', '/community'];
    const isPublicRoute = publicRoutes.some(route => pathname === route || pathname.startsWith(route));

    if (isPublicRoute) {
      setChecked(true)
      return
    }

    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null

    if (!token) {
      router.replace('/auth')
      return
    }

    setChecked(true)
  }, [pathname, router])

  // Evite le rendu tant que la vérif n'est pas faite (évite flicker)
  if (!checked && !pathname?.startsWith('/auth')) return null

  return <>{children}</>
}